-- Conferencias antes de confirmar: uma falha impede a confirmacao.
DO $validar_carga$
BEGIN
    IF (SELECT COUNT(*) FROM public.clientes WHERE cliente_id BETWEEN 10001 AND 22000) <> 12000
       OR (SELECT COUNT(*) FROM public.pedidos WHERE pedido_id BETWEEN 20001 AND 40000) <> 20000
       OR (SELECT COUNT(*) FROM public.itens_pedido WHERE pedido_id BETWEEN 20001 AND 40000) <> 60000
    THEN
        RAISE EXCEPTION 'Contagem inesperada na carga. Execute ROLLBACK e confira o arquivo.';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.pedidos AS p
        LEFT JOIN public.itens_pedido AS i ON i.pedido_id = p.pedido_id
        WHERE p.pedido_id BETWEEN 20001 AND 40000
        GROUP BY p.pedido_id, p.valor_total
        HAVING COUNT(i.produto_id) = 0
           OR p.valor_total <> SUM(i.quantidade * i.preco_unitario)
    ) THEN
        RAISE EXCEPTION 'Pedido novo sem itens ou com total divergente. Execute ROLLBACK.';
    END IF;
END;
$validar_carga$;

COMMIT;

-- Resumo APENAS do lote novo; dados antigos nao entram nestas contagens.
SELECT 'clientes novos' AS conjunto, COUNT(*) AS quantidade
FROM public.clientes WHERE cliente_id BETWEEN 10001 AND 22000
UNION ALL
SELECT 'pedidos novos', COUNT(*)
FROM public.pedidos WHERE pedido_id BETWEEN 20001 AND 40000
UNION ALL
SELECT 'linhas de itens novas', COUNT(*)
FROM public.itens_pedido WHERE pedido_id BETWEEN 20001 AND 40000;
